/**
 * Deux creneaux se chevauchent-ils ?
 *
 * Les bornes sont des dates ISO 8601. Un creneau est [debut, fin[.
 */
export function overlaps(aStart: string, aEnd: string, bStart: string, bEnd: string): boolean {
  const a1 = Date.parse(aStart);
  const a2 = Date.parse(aEnd);
  const b1 = Date.parse(bStart);
  const b2 = Date.parse(bEnd);
  return a1 < b2 && b1 < a2;
}

export default overlaps;

import { Router } from "express";
import { rooms, findRoom, bookingsForRoom } from "../store.js";

export const roomsRouter = Router();

interface Slot {
  startsAt: string;
  endsAt: string;
}

function parseDay(value: unknown): Date | undefined {
  if (typeof value !== "string" || !/^\d{4}-\d{2}-\d{2}$/.test(value)) {
    return undefined;
  }

  const day = new Date(`${value}T00:00:00.000Z`);
  return day.toISOString().startsWith(value) ? day : undefined;
}

function availabilityForRoom(roomId: string, date: string): Slot[] {
  const dayStart = Date.parse(`${date}T00:00:00.000Z`);
  const dayEnd = dayStart + 24 * 60 * 60 * 1000;
  const busy = bookingsForRoom(roomId)
    .map((booking) => ({
      startsAt: Math.max(Date.parse(booking.startsAt), dayStart),
      endsAt: Math.min(Date.parse(booking.endsAt), dayEnd)
    }))
    .filter((slot) => slot.startsAt < slot.endsAt)
    .sort((a, b) => a.startsAt - b.startsAt);

  const available: Slot[] = [];
  let cursor = dayStart;

  for (const slot of busy) {
    if (cursor < slot.startsAt) {
      available.push({
        startsAt: new Date(cursor).toISOString(),
        endsAt: new Date(slot.startsAt).toISOString()
      });
    }
    cursor = Math.max(cursor, slot.endsAt);
  }

  if (cursor < dayEnd) {
    available.push({
      startsAt: new Date(cursor).toISOString(),
      endsAt: new Date(dayEnd).toISOString()
    });
  }

  return available;
}

roomsRouter.get("/", (_req, res) => {
