roomsRouter.get("/:id/availability", (req, res) => {
  const room = findRoom(req.params.id);
  if (!room) {
    res.status(404).json({ error: "salle inconnue" });
    return;
  }

  const day = parseDay(req.query.date);
  if (!day) {
    res.status(400).json({ error: "date invalide : format YYYY-MM-DD attendu" });
    return;
  }

  const date = day.toISOString().slice(0, 10);
  res.json({ room, date, available: availabilityForRoom(room.id, date) });
});

